{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table maplemonk.CC_sales_consolidated_intermediate as SELECT CAST(region AS STRING) AS region, upper(delivery_country) delivery_country, CAST(cust_id AS STRING) AS customer_id, upper(CAST(Business_Segment AS STRING)) AS Business_Segment, upper(CAST(Brand AS STRING)) AS Brand, upper(CAST(marketplace AS STRING)) AS Shop_name, upper(CAST(marketplace AS STRING)) AS marketplace, upper(coalesce(Affiliates,order_channel,CAST(ga4.channel AS STRING),CAST(marketplace AS STRING))) AS CHANNEL, upper(coalesce(Affiliates,order_channel,CAST(ga4.final_source AS STRING),CAST(marketplace AS STRING))) AS SOURCE, CAST(order_id AS STRING) AS order_id, CAST(reference_code AS STRING) AS reference_code, CAST(cust_id AS STRING) AS phone, CAST(name AS STRING) AS name, CAST(email AS STRING) AS email, CAST(order_modified_date AS TIMESTAMP) AS SHIPPING_LAST_UPDATE_DATE, CAST(product_id AS STRING) AS sku, CAST(product_id AS STRING) AS product_id, CAST(product_name AS STRING) AS product_name, CAST(currency_code AS STRING) AS CURRENCY, upper(CAST(City AS STRING)) AS City, upper(CAST(State AS STRING)) AS State, CAST(Order_Status AS STRING) AS Order_Status, CAST(order_date AS DATE) AS order_date, CAST(order_timestamp AS TIMESTAMP) AS Order_Time, CAST(product_qty AS FLOAT64) AS quantity, CAST(total_price AS FLOAT64) AS GROSS_SALES_BEFORE_TAX, CAST(discount AS FLOAT64) AS DISCOUNT, CAST(TAX AS FLOAT64) AS TAX, CAST(SHIPPING_PRICE AS FLOAT64) AS SHIPPING_PRICE, CAST(total_price AS FLOAT64) AS SELLING_PRICE, CAST(UPPER(order_status) AS STRING) AS OMS_order_status, CAST(UPPER(order_status) AS STRING) AS SHIPPING_STATUS, CAST(UPPER(order_status) AS STRING) AS FINAL_SHIPPING_STATUS, CAST(CONCAT(afi.ORDER_ID, \'-\', afi.PRODUCT_ID) AS STRING) AS SALEORDERITEMCODE, CAST(CONCAT(afi.ORDER_ID, \'-\', afi.PRODUCT_ID) AS STRING) AS SALES_ORDER_ITEM_ID, CAST(AWB AS STRING) AS AWB, CAST(Payment_Gateway AS STRING) AS Payment_Gateway, CAST(NULL AS STRING) AS Payment_Mode, CAST(courier_name AS STRING) AS COURIER, CAST(dispatched_date AS TIMESTAMP) AS DISPATCH_DATE, CAST(paid_date AS TIMESTAMP) AS paid_date, CAST(NULL AS TIMESTAMP) AS DELIVERED_DATE, CASE WHEN LOWER(order_status) LIKE \'delive%\' THEN 1 ELSE 0 END AS DELIVERED_STATUS, CASE WHEN prod_returned_date IS NOT NULL THEN 1 ELSE 0 END AS RETURN_FLAG, CAST(prod_return_qty AS FLOAT64) AS returned_quantity, CAST(prod_refund_amount AS FLOAT64) AS returned_sales, CASE WHEN LOWER(afi.order_status) LIKE \'cancel%\' THEN CAST(afi.product_qty AS FLOAT64) END AS cancelled_quantity, CAST(NULL AS STRING) AS NEW_CUSTOMER_FLAG, CAST(NULL AS STRING) AS ACQUISITION_PRODUCT, CASE WHEN LOWER(order_status) IN (\'delivered\', \'delivered to origin\') THEN DATE_DIFF(CAST(CURRENT_DATE() AS DATE), CAST(afi.ORDER_TIMESTAMP AS DATE), DAY) WHEN LOWER(order_status) IN (\'in transit\', \'shipment created\') THEN DATE_DIFF(CAST(CURRENT_DATE() AS DATE), CAST(afi.ORDER_TIMESTAMP AS DATE), DAY) END AS Days_in_Shipment, CAST(afi.SKU AS STRING) AS SKU_CODE, CAST(UPPER(AFI.product_name) AS STRING) AS PRODUCT_NAME_FINAL, CAST(UPPER(AFI.PRODUCT_CATEGORY) AS STRING) AS PRODUCT_CATEGORY, CAST(PRODUCT_SUB_CATEGORY AS STRING) AS PRODUCT_SUB_CATEGORY, CAST(afi.SKU AS STRING) AS commonsku, CAST(NULL AS STRING) AS WAREHOUSE, CAST(zipcode AS STRING) AS pincode, CAST(NULL AS STRING) AS source_pincode, CAST(NULL AS STRING) AS discount_codes, CAST(prod_returned_date AS TIMESTAMP) Return_date FROM maplemonk.website_marketplace_fact_items AS afi left join ( select transactionid, final_source, channel from maplemonk.CC_GA_ORDER_BY_SOURCE_CONSOLIDATED qualify row_number() over (partition by transactionid order by 1) =1 ) GA4 on replace(cast(AFI.order_id as string),\'#\',\'\') = replace(GA4.transactionid, \'#\',\'\') ; CREATE OR REPLACE TABLE maplemonk.Final_customerID AS WITH new_phone_numbers AS ( SELECT phone, contact_num, 19700000000 + ROW_NUMBER() OVER (ORDER BY contact_num ASC) AS maple_monk_id FROM ( SELECT DISTINCT phone AS contact_num, phone FROM maplemonk.CC_sales_consolidated_intermediate ) a ), INT AS ( SELECT contact_num, email, COALESCE(maple_monk_id, id2) AS maple_monk_id FROM ( SELECT contact_num, email, maple_monk_id, 19800000000 + ROW_NUMBER() OVER (PARTITION BY maple_monk_id IS NULL ORDER BY email ASC) AS id2 FROM ( SELECT DISTINCT COALESCE(p.contact_num,e.contact_num) AS contact_num, e.email, maple_monk_id FROM ( SELECT phone AS contact_num, email FROM maplemonk.CC_sales_consolidated_intermediate ) e LEFT JOIN new_phone_numbers p ON p.contact_num = e.contact_num ) a ) b ) SELECT contact_num, email, maple_monk_id FROM INT WHERE COALESCE(contact_num, email) IS NOT NULL; CREATE OR REPLACE TABLE maplemonk.CC_sales_consolidated AS SELECT COALESCE(m.maple_monk_id_phone, d.maple_monk_id) AS customer_id_final, MIN(order_date) OVER (PARTITION BY COALESCE(m.maple_monk_id_phone, d.maple_monk_id)) AS acquisition_date, MIN(CASE WHEN LOWER(order_status) NOT IN (\'cancelled\') THEN order_date END) OVER (PARTITION BY COALESCE(m.maple_monk_id_phone, d.maple_monk_id)) AS first_complete_order_date, sum(ifnull(quantity, 0)) over(partition by reference_code order by 1) Order_Quantity, m.* FROM ( SELECT c.maple_monk_id AS maple_monk_id_phone, o.* FROM maplemonk.CC_sales_consolidated_intermediate o LEFT JOIN ( SELECT * FROM ( SELECT contact_num AS phone, maple_monk_id, ROW_NUMBER() OVER (PARTITION BY contact_num ORDER BY maple_monk_id ASC) AS magic FROM maplemonk.Final_customerID ) WHERE magic = 1 ) c ON c.phone = o.phone ) m LEFT JOIN ( SELECT DISTINCT maple_monk_id, email FROM maplemonk.Final_customerID WHERE contact_num IS NULL ) d ON d.email = m.email ; ALTER TABLE maplemonk.CC_sales_consolidated DROP COLUMN IF EXISTS new_customer_flag, DROP COLUMN IF EXISTS acquisition_product; ALTER TABLE maplemonk.CC_sales_consolidated ADD COLUMN new_customer_flag STRING, ADD COLUMN new_customer_flag_month STRING, ADD COLUMN acquisition_product STRING, ADD COLUMN acquisition_channel STRING, ADD COLUMN acquisition_marketplace STRING; UPDATE maplemonk.CC_sales_consolidated AS A SET A.new_customer_flag = B.flag FROM ( SELECT order_id, customer_id_final, Order_Date, CASE WHEN Order_Date = first_complete_order_date THEN \'New\' WHEN Order_Date < first_complete_order_date OR first_complete_order_date IS NULL THEN \'Yet to make completed order\' WHEN Order_Date > first_complete_order_date THEN \'Repeat\' END AS Flag, row_number() over (partition by order_id, customer_id_final order by order_date) rw FROM maplemonk.CC_sales_consolidated ) AS B WHERE A.order_id = B.order_id AND A.customer_id_final = B.customer_id_final and rw =1; UPDATE maplemonk.CC_sales_consolidated SET new_customer_flag = CASE WHEN new_customer_flag IS NULL AND (LOWER(order_status) IS NULL OR LOWER(order_status) NOT IN (\'cancelled\')) THEN \'New\' WHEN new_customer_flag IS NULL AND LOWER(order_status) IN (\'cancelled\') THEN \'Yet to make completed order\' ELSE new_customer_flag END WHERE new_customer_flag IS NULL; UPDATE maplemonk.CC_sales_consolidated AS A SET A.new_customer_flag_month = B.flag FROM ( SELECT DISTINCT order_id, customer_id_final, order_date, CASE WHEN DATE_TRUNC(order_date, MONTH) = DATE_TRUNC(first_complete_order_date, MONTH) THEN \'New\' WHEN DATE_TRUNC(order_date, MONTH) < DATE_TRUNC(first_complete_order_date, MONTH) OR acquisition_date IS NULL THEN \'Yet to make completed order\' WHEN DATE_TRUNC(order_date, MONTH) > DATE_TRUNC(first_complete_order_date, MONTH) THEN \'Repeat\' END AS flag, row_number() over (partition by order_id, customer_id_final order by order_date) rw FROM maplemonk.CC_sales_consolidated ) AS B WHERE A.order_id = B.order_id AND A.customer_id_final = B.customer_id_final and rw=1; UPDATE maplemonk.CC_sales_consolidated SET new_customer_flag_month = CASE WHEN new_customer_flag_month IS NULL AND (LOWER(order_status) IS NULL OR LOWER(order_status) NOT IN (\'cancelled\')) THEN \'New\' ELSE new_customer_flag_month END WHERE new_customer_flag_month IS NULL; CREATE OR REPLACE TEMPORARY TABLE temp_source_1 AS SELECT customer_id_final, source AS channel, shop_name AS marketplace FROM (SELECT * FROM( SELECT customer_id_final, order_date, source, shop_name, MIN(CASE WHEN LOWER(order_status) <> \'cancelled\' THEN order_date END) OVER (PARTITION BY customer_id_final) AS firstOrderDate, row_number() over (partition by customer_id_final order by ORDER_TIME) rw FROM maplemonk.CC_sales_consolidated ) AS res where rw =1 ) WHERE order_date = firstOrderDate; UPDATE maplemonk.CC_sales_consolidated AS a SET a.acquisition_channel = b.channel FROM temp_source_1 AS b WHERE a.customer_id_final = b.customer_id_final; UPDATE maplemonk.CC_sales_consolidated AS a SET a.acquisition_marketplace = b.marketplace FROM temp_source_1 AS b WHERE a.customer_id_final = b.customer_id_final; CREATE OR replace temporary TABLE temp_product_1 AS SELECT customer_id_final, product_name_final FROM ( SELECT customer_id_final, order_date, product_name_final, SELLING_PRICE , Min(case when lower(order_status) <> \'cancelled\' then order_date end) OVER (partition BY customer_id_final) firstOrderdate, row_number() over (partition by customer_id_final order by ORDER_TIME asc, SELLING_PRICE desc) rw FROM maplemonk.CC_sales_consolidated )res WHERE order_date=firstorderdate and rw=1; UPDATE maplemonk.CC_sales_consolidated AS A SET A.acquisition_product = B.product_name_final FROM ( SELECT * FROM temp_product_1 ) AS B WHERE A.customer_id_final = B.customer_id_final;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            